Следующий код создаст бота Discord с одной командой бан:

```javascript
const { SlashCommandBuilder } = require('discord.js');

const { DISCORD_TOKEN } = require('./config');

const client = new Discord.Client();

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    if (!interaction.member.permissions.has(Discord.PermissionFlagsBits.BanMembers)) {
      return interaction.reply({ content: 'You do not have permission to ban members.', ephemeral: true });
    }

    const member = interaction.options.getMember('user');
    if (!member) {
      return interaction.reply({ content: 'Please provide a valid user to ban.', ephemeral: true });
    }

    if (member.id === client.user.id) {
      return interaction.reply({ content: 'I cannot ban myself.', ephemeral: true });
    }

    await interaction.member.guild.members.ban(member, { days: 7, reason: 'Banned by bot command' });

    return interaction.reply({ content: `${member.user.tag} has been banned.`, ephemeral: false });
  }
});

const buildCommand = (name, description) => {
  return new SlashCommandBuilder()
    .setName(name)
    .setDescription(description);
};

const commands = [
  buildCommand('ban', 'Bans a user from the server.')
];

client.on('ready', () => {
  client.application.commands.set(commands);
});

client.login(DISCORD_TOKEN);
```

В приведенном выше коде:

1. Импортируйте `SlashCommandBuilder` из `discord.js`.
2. Получите токен Discord из файла конфигурации.
3. Создайте новый экземпляр `Discord.Client()`.
4. Настройте обработчики событий `ready` и `interactionCreate` для вашего бота.
5. С помощью `SlashCommandBuilder`, создайте команду бан с именем `ban`.
6. Создайте массив команд и передайте его в `application.commands.set()` для регистрации команд в Discord.
7. Включите бота с помощью токена Discord.

При выполнении этого кода, ваш бот сможет реагировать на команду `/ban`, которая позволит администраторам банить пользователей на вашем сервере Discord. Обратите внимание, что для выполнения этой команды, администратор должен иметь разрешение на банирование участников.

Вот пример функции C++, которая принимает ссылку на std::string, содержащую текст в формате уценки, и возвращает std::string, содержащий текст в формате HTML:

```cpp
#include <iostream>
#include <string>
#include <regex>

std::string convertToHtml(const std::string& inputText) {
    std::string htmlText;

    // Replace opening and closing angle brackets with HTML entities
    std::regex angleBracketRegex("<");
    std::regex::flag_type regexFlags = std::regex::icase;
    std::string replacement = "&lt;";
    std::regex_replace(htmlText, angleBracketRegex, replacement, regexFlags);

    std::regex angleBracketRegex2(">");
    std::regex::flag_type regexFlags2 = std::regex::icase;
    std::string replacement2 = "&gt;";
    std::regex_replace(htmlText, angleBracketRegex2, replacement2, regexFlags2);

    // Wrap text in `<em>` tags for italicized text
    std::regex italicRegex("_([^_]+)_");
    std::regex::flag_type regexFlags3 = std::regex::icase;
    std::string replacement3 = "<em>$1</em>";
    std::regex_replace(htmlText, italicRegex, replacement3, regexFlags3);

    // Wrap text in `<strong>` tags for bolded text
    std::regex boldRegex("__([^_]+)__");
    std::regex::flag_type regexFlags4 = std::regex::icase;
    std::string replacement4 = "<strong>$1</strong>";
    std::regex_replace(htmlText, boldRegex, replacement4, regexFlags4);

    return htmlText;
}

int main() {
    std::string inputText = "This is some _italicized__and__bolded_ text.";
    std::string htmlText = convertToHtml(inputText);

    std::cout << "Input text: " << inputText << std::endl;
    std::cout << "Converted HTML text: " << htmlText << std::endl;

    return 0;
}
```

В этой функции, мы начинаем с создания пустой строки `htmlText`, которая будет содержать преобразованный текст в формате HTML.

Затем мы применяем регулярные выражения для замены символов открывающего и закрывающего угловых скобок на соответствующие HTML-сущности `<` и `>`.

Далее, мы определяем регулярные выражения для выделения текста в уценках и добавляем соответствующие HTML-теги `<em>` для курсива и `<strong>` для полужирного шрифта.

В конце, мы возвращаем преобразованную строку в формате HTML.

В примере выше, функция преобразует входную строку в формат HTML, который будет выглядеть так:

```
Converted HTML text: <em>This is some <strong>italicized</strong>&__and__bolded</strong> text.</em>
```

Чтобы создать игру «Змейка» на C с плавной анимацией и использованием изображений для уровня, вам потребуется:

1. Существующая библиотека для работы с графическим интерфейсом (GUI), такой как SDL, SFML или GLFW.
2. Установить и настроить редактор графических ресурсов, такой как Adobe Photoshop, GIMP или Krita, для создания и редактирования изображений.

Далее приведен пример высокого уровня для создания игры «Змейка» на C с плавной анимацией и использованием изображений для уровня:

1. Создайте новый проект в редакторе графических ресурсов и создайте набор спрайтов для змейки и пищи в формате PNG. Каждый спрайт должен иметь разные фазы движения, чтобы создавать иллюзию плавности.

2. Настройте среду разработки C, чтобы использовать библиотеку GUI, которую вы выберете. В примере мы будем использовать SDL.

3. Создайте файл с именем `snake.c` и добавьте следующие заголовки:

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
```

4. Создайте функцию `initSDL()` для инициализации SDL и загрузки изображений:

```c
static SDL_Window *window;
static SDL_Renderer *renderer;

static SDL_Texture *snake_head_texture;
static SDL_Texture *snake_body_texture;
static SDL_Texture *food_texture;

static int snake_head_width, snake_head_height;
static int snake_body_width, snake_body_height;
static int food_width, food_height;

static int snake_speed;

static SDL_Rect snake_head_rect;
static SDL_Rect snake_body_rect;
static SDL_Rect food_rect;

static int snake_x, snake_y;
static int snake_length;
static int food_x, food_y;

static int running;

static void initSDL() {
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL initialization failed: %s\n", SDL_GetError());
        exit(EXIT_FAILURE);
    }

    window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        800, 600,
        SDL_WINDOW_SHOWN
    );

    if (!window) {
        printf("Window creation failed: %s\n", SDL_GetError());
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    if (!renderer) {
        printf("Renderer creation failed: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    // Load textures
    snake_head_texture = IMG_LoadTexture(renderer, "snake_head.png");
    snake_body_texture = IMG_LoadTexture(renderer, "snake_body.png");
    food_texture = IMG_LoadTexture(renderer, "food.png");

    if (!snake_head_texture || !snake_body_texture || !food_texture) {
        printf("Texture loading failed: %s\n", SDL_GetError());
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        exit(EXIT_FAILURE);
    }

    // Get texture dimensions
    SDL_QueryTexture(snake_head_texture, NULL, NULL, &snake_head_width, &snake_head_height);
    SDL_QueryTexture(snake_body_texture, NULL, NULL, &snake_body_width, &snake_body_height);
    SDL_QueryTexture(food_texture, NULL, NULL, &food_width, &food_height);

    // Initialize snake and food positions
    snake_length = 3;
    snake_x = 400 - (snake_length - 1) * snake_body_width;
    snake_y = 300;
    food_x = rand() % (800 / food_width);
    food_y = rand() % (600 / food_height);

    // Initialize snake head rectangle
    snake_head_rect.x = snake_x;
    snake_head_rect.y = snake_y;
    snake_head_rect.w = snake_head_width;
    snake_head_rect.h = snake_head_height;

    // Initialize snake body rectangles
    snake_body_rect.x = snake_x - snake_body_width;
    snake_body_rect.y = snake_y;
    snake_body_rect.w = snake_body_width;
    snake_body_rect.h = snake_body_height;

    snake_speed = 5;

    running = 1;
}
```

5. Создайте функцию `handleInput()` для обработки ввода игрока:

```c
static void handleInput(SDL_Event *event) {
    switch (event->type) {
        case SDL_KEYDOWN:
            switch (event->key.keysym.sym) {
                case SDLK_LEFT:
                    if (snake_x > 0) {
                        snake_x -= snake_body_width;
                    }
                    break;
                case SDLK_RIGHT:
                    if (snake_x + snake_head_width < 800) {
                        snake_x += snake_body_width;
                    }
                    break;
                case SDLK_UP:
                    if (snake_y > 0) {
                        snake_y -= snake_body_height;
                    }
                    break;
                case SDLK_DOWN:
                    if (snake_y + snake_head_height < 600) {
                        snake_y += snake_body_height;
                    }
                    break;
            }
            break;
    }
}
```

6. Создайте функцию `update()` для обновления игры:

```c
static void update() {
    // Move snake head
    snake_head_rect.x += snake_speed;

    // Check for snake collision
    for (int I = 1; I < snake_length; i++) {
        if (snake_head_rect.x == snake_body_rect.x + I * snake_body_width &&
            snake_head_rect.y == snake_body_rect.y) {
            running = 0;
            break;
        }
    }

    // Check for food collision
    if (snake_head_rect.x >= food_x &&
        snake_head_rect.x + snake_head_width <= food_x + food_width &&
        snake_head_rect.y >= food_y &&
        snake_head_rect.y + snake_head_height <= food_y + food_height) {
        snake_length++;
        food_x = rand() % (800 / food_width);
        food_y = rand() % (600 / food_height);
    }

    // Move snake body
    for (int I = snake_length - 2; I >= 0; i--) {
        snake_body_rect.x = snake_body_rect.x + snake_speed;
        snake_body_rect.y = snake_body_rect.y;
        snake_body_rect.w = snake_body_width;
        snake_body_rect.h = snake_body_height;

        snake_body_rect.x = snake_body_rect.x - snake_body_width;
    }
}
```

7. Созда 

```c
static void render() {
    SDL_SetRenderDrawColor(renderer, 0xFF, 0xFF, 0xFF, 0xFF);
    SDL_RenderClear(renderer);

    // Draw snake head
    SDL_RenderCopy(renderer, snake_head_texture, NULL, &snake_head_rect);

    // Draw snake body
    for (int I = 1; I < snake_length; i++) {
        SDL_RenderCopy(renderer, snake_body_texture, NULL, &snake_body_rect);
        snake_body_rect.x += snake_body_width;
    }

    // Draw food
    SDL_RenderCopy(renderer, food_texture, NULL, &food_rect);

    SDL_RenderPresent(renderer);
}
```

8. Создайте функцию `main()` для запуска игры:

```c
int main(int argc, char *argv[]) {
    initSDL();

    while (running) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            handleInput(&event);
        }
        update();
        render();
        SDL_Delay(16);
    }

    SDL_DestroyTexture(snake_head_texture);
    SDL_DestroyTexture(snake_body_texture);
    SDL_DestroyTexture(food_texture);

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);

    SDL_Quit();

    return 0;
}
```

9. Скомпилируйте и запустите вашу игру, и наслаждайтесь игрой «Змейка» с плавной анимацией и изображениями для уровня!

