Следующий код на C++ читает текстовый файл построчно и подсчитывает количество вхождений определенного слова в файл:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    std::string word; // Слово, которое необходимо искать
    std::cout << "Enter the word to search: ";
    std::getline(std::cin, word);

    std::string filename;
    std::cout << "Enter the filename: ";
    std::getline(std::cin, filename);

    std::ifstream file(filename);
    if (!file.is_open()) {
        std::cerr << "Error: Unable to open file." << std::endl;
        return 1;
    }

    int count = 0; // Счетчик вхождений слова

    std::string line;
    while (std::getline(file, line)) {
        std::transform(line.begin(), line.end(), line.begin(), ::tolower); // Преобразовать все символы строки в нижний регистр

        std::size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) {
            ++count;
            pos += word.length(); // Переходить к следующему вхождению слова
        }
    }

    file.close();

    std::cout << "The word \"" << word << "\" appears " << count << " times in " << filename << "." << std::endl;

    return 0;
}
```

В этом примере, вам необходимо ввести слово, которое необходимо искать, и имя файла. Программа будет считывать файл построчно, преобразовать все символы строки в нижний регистр, и подсчитывать количество вхождений слова. После завершения чтения файла, программа выведет количество вхождений слова в консоль.  Пожалуйста, не забудьте включить <algorithm> для использования функции std::transform().
